<?php
declare(strict_types=1);
require __DIR__ . '/../../../../lib/app.php';
app_require_mode([0,1,2]);
$db=app_db();$id=app_int('id');
$record=$id?$db->one('SELECT * FROM ofertas WHERE id=?','i',[$id]):null;
if($id&&!$record){http_response_code(404);exit('Oferta inexistente.');}
$categories=$db->all('SELECT c.id,c.nombre,n.nombre nivel FROM catalogo_categorias c JOIN catalogo_niveles n ON n.id=c.nivel_id WHERE c.activo=1 AND c.admite_ofertas=1 ORDER BY n.orden,c.nombre');
$units=$db->all('SELECT id,nombre FROM unidades_academicas WHERE activo=1 ORDER BY nombre');
$modalities=$db->all('SELECT id,nombre FROM modalidades WHERE activo=1 ORDER BY orden');
$shifts=$db->all('SELECT id,nombre FROM turnos WHERE activo=1 ORDER BY orden');
$areas=$db->all('SELECT id,nombre FROM areas_conocimiento WHERE activo=1 ORDER BY orden');
$selectedShifts=$id?array_map('intval',array_column($db->all('SELECT turno_id FROM oferta_turno WHERE oferta_id=?','i',[$id]),'turno_id')):[];
$selectedAreas=$id?array_map('intval',array_column($db->all('SELECT area_id FROM oferta_area WHERE oferta_id=?','i',[$id]),'area_id')):[];
$call=$id?$db->one("SELECT * FROM oferta_convocatorias WHERE oferta_id=? ORDER BY CASE estado WHEN 'abierta' THEN 0 WHEN 'programada' THEN 1 ELSE 2 END,anio DESC,id DESC LIMIT 1",'i',[$id]):null;
?>
<div class="card admin-card mb-4"><div class="card-body p-4"><div class="d-flex justify-content-between align-items-start"><div><h2 class="h5 mb-1"><?=$id?'Editar oferta':'Nueva oferta'?></h2><p class="text-secondary small mb-0">Los campos marcados son obligatorios. Guardar como borrador permite completar la información más adelante.</p></div><button class="btn-close" type="button" onclick="$('#offers-panel').empty()" aria-label="Cerrar"></button></div>
<form id="offer-admin-form" class="row g-3 mt-1"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$id?>">
<div class="col-md-8"><label class="form-label required">Título</label><input class="form-control" name="titulo" maxlength="200" required value="<?=app_escape($record['titulo']??'')?>"></div><div class="col-md-4"><label class="form-label">Slug <span class="text-secondary">(automático si queda vacío)</span></label><input class="form-control" name="slug" maxlength="160" value="<?=app_escape($record['slug']??'')?>"></div>
<div class="col-md-6"><label class="form-label required">Categoría hoja</label><select class="form-select" name="categoria_id" required><option value="">Seleccionar</option><?php foreach($categories as $category):?><option value="<?=(int)$category['id']?>" <?=((int)($record['categoria_id']??0)===(int)$category['id'])?'selected':''?>><?=app_escape($category['nivel'].' · '.$category['nombre'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label required">Modalidad</label><select class="form-select" name="modalidad_id" required><option value="">Seleccionar</option><?php foreach($modalities as $item):?><option value="<?=(int)$item['id']?>" <?=((int)($record['modalidad_id']??0)===(int)$item['id'])?'selected':''?>><?=app_escape($item['nombre'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Unidad académica</label><select class="form-select" name="unidad_academica_id"><option value="">Sin especificar</option><?php foreach($units as $item):?><option value="<?=(int)$item['id']?>" <?=((int)($record['unidad_academica_id']??0)===(int)$item['id'])?'selected':''?>><?=app_escape($item['nombre'])?></option><?php endforeach;?></select></div>
<div class="col-12"><label class="form-label">Resumen para la tarjeta</label><textarea class="form-control" name="resumen" rows="2" maxlength="500"><?=app_escape($record['resumen']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Descripción</label><textarea class="form-control" name="descripcion" rows="5"><?=app_escape($record['descripcion']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Perfil del egresado</label><textarea class="form-control" name="perfil_egresado" rows="5"><?=app_escape($record['perfil_egresado']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Requisitos de ingreso</label><textarea class="form-control" name="requisitos_ingreso" rows="4"><?=app_escape($record['requisitos_ingreso']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Título o certificación otorgada</label><input class="form-control" name="titulo_otorgado" maxlength="200" value="<?=app_escape($record['titulo_otorgado']??'')?>"><label class="form-label mt-3">Norma de aprobación</label><input class="form-control" name="norma_aprobacion" maxlength="200" value="<?=app_escape($record['norma_aprobacion']??'')?>"></div>
<div class="col-md-2"><label class="form-label">Duración</label><input class="form-control" type="number" name="duracion_valor" min="0" max="9999" step="0.5" value="<?=app_escape($record['duracion_valor']??'')?>"></div><div class="col-md-3"><label class="form-label">Unidad de duración</label><select class="form-select" name="duracion_unidad"><option value="">Sin especificar</option><?php foreach(['anios'=>'Años','cuatrimestres'=>'Cuatrimestres','meses'=>'Meses','semanas'=>'Semanas','horas'=>'Horas'] as $value=>$label):?><option value="<?=$value?>" <?=($record['duracion_unidad']??'')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Carga horaria</label><input class="form-control" type="number" name="carga_horaria" min="0" max="65535" value="<?=app_escape($record['carga_horaria']??'')?>"></div><div class="col-md-5"><label class="form-label">URL de imagen</label><input class="form-control" type="url" name="imagen_url" maxlength="500" value="<?=app_escape($record['imagen_url']??'')?>"></div>
<div class="col-md-6"><label class="form-label">Turnos</label><div class="d-flex flex-wrap gap-3 border rounded p-3"><?php foreach($shifts as $item):?><label class="form-check"><input class="form-check-input" type="checkbox" name="turnos[]" value="<?=(int)$item['id']?>" <?=in_array((int)$item['id'],$selectedShifts,true)?'checked':''?>><span class="form-check-label"><?=app_escape($item['nombre'])?></span></label><?php endforeach;?></div></div><div class="col-md-6"><label class="form-label">Áreas de conocimiento</label><div class="d-flex flex-wrap gap-3 border rounded p-3"><?php foreach($areas as $item):?><label class="form-check"><input class="form-check-input" type="checkbox" name="areas[]" value="<?=(int)$item['id']?>" <?=in_array((int)$item['id'],$selectedAreas,true)?'checked':''?>><span class="form-check-label"><?=app_escape($item['nombre'])?></span></label><?php endforeach;?></div></div>
<div class="col-md-3"><label class="form-label required">Estado de la oferta</label><select class="form-select" name="estado_oferta" required><?php foreach(['proximamente'=>'Próximamente','inscripcion_abierta'=>'Inscripción abierta','en_curso'=>'En curso','a_termino'=>'A término','cerrada'=>'Cerrada'] as $value=>$label):?><option value="<?=$value?>" <?=($record['estado_oferta']??'proximamente')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label required">Publicación</label><select class="form-select" name="estado_publicacion" required><?php foreach(['borrador'=>'Borrador','publicada'=>'Publicada','archivada'=>'Archivada'] as $value=>$label):?><option value="<?=$value?>" <?=($record['estado_publicacion']??'borrador')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Orden</label><input class="form-control" type="number" name="orden" min="0" max="65535" value="<?=(int)($record['orden']??0)?>"></div><div class="col-md-4 d-flex align-items-end"><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="destacada" value="1" <?=!empty($record['destacada'])?'checked':''?>><span class="form-check-label">Mostrar como oferta destacada</span></label></div>
<div class="col-12"><hr><h3 class="h6">Convocatoria actual <span class="text-secondary fw-normal">(opcional)</span></h3></div><input type="hidden" name="convocatoria_id" value="<?=(int)($call['id']??0)?>"><div class="col-md-2"><label class="form-label">Año</label><input class="form-control" type="number" name="convocatoria_anio" min="2000" max="2100" value="<?=app_escape($call['anio']??'')?>"></div><div class="col-md-2"><label class="form-label">Edición</label><input class="form-control" name="convocatoria_edicion" maxlength="40" value="<?=app_escape($call['edicion']??'')?>"></div><div class="col-md-2"><label class="form-label">Inscripción desde</label><input class="form-control" type="date" name="inscripcion_desde" value="<?=app_escape($call['inscripcion_desde']??'')?>"></div><div class="col-md-2"><label class="form-label">Inscripción hasta</label><input class="form-control" type="date" name="inscripcion_hasta" value="<?=app_escape($call['inscripcion_hasta']??'')?>"></div><div class="col-md-2"><label class="form-label">Estado</label><select class="form-select" name="convocatoria_estado"><?php foreach(['programada'=>'Programada','abierta'=>'Abierta','cerrada'=>'Cerrada','finalizada'=>'Finalizada'] as $value=>$label):?><option value="<?=$value?>" <?=($call['estado']??'programada')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Cupo</label><input class="form-control" type="number" name="convocatoria_cupo" min="0" max="65535" value="<?=app_escape($call['cupo']??'')?>"></div><div class="col-12"><label class="form-label">URL de preinscripción</label><input class="form-control" type="url" name="url_preinscripcion" maxlength="500" value="<?=app_escape($call['url_preinscripcion']??'')?>"></div>
<div class="col-12 d-flex justify-content-end gap-2"><button class="btn btn-light" type="button" onclick="$('#offers-panel').empty()">Cancelar</button><button class="btn btn-primary" type="submit">Guardar oferta</button></div>
</form></div></div>
<script>$('#offer-admin-form').on('submit',function(e){e.preventDefault();appAction('modulos/ofertas/php/app_action.php',$(this).serialize(),offersAdminReload);});</script>
